<?php
namespace App\Http\Controllers;
use App\Models\SuratKeluar;
use Illuminate\Http\Request;
class SuratKeluarController extends Controller { public function index(Request $r){$q=$r->string('q');$data=SuratKeluar::when($q,fn($x)=>$x->where('nomor','like',"%$q%")->orWhere('tujuan','like',"%$q%")->orWhere('perihal','like',"%$q%"))->latest('tanggal')->paginate(15)->withQueryString();return view('surat-keluar.index',compact('data','q'));} public function create(){return view('surat-keluar.form',['item'=>new SuratKeluar]);} public function store(Request $r){$d=$r->validate(['nomor'=>'required','tanggal'=>'required|date','tujuan'=>'required','perihal'=>'required','keterangan'=>'nullable']);SuratKeluar::create($d);return redirect()->route('surat-keluar.index')->with('success','Surat keluar berhasil disimpan.');} public function edit(SuratKeluar $suratKeluar){return view('surat-keluar.form',['item'=>$suratKeluar]);} public function update(Request $r,SuratKeluar $suratKeluar){$d=$r->validate(['nomor'=>'required','tanggal'=>'required|date','tujuan'=>'required','perihal'=>'required','keterangan'=>'nullable']);$suratKeluar->update($d);return redirect()->route('surat-keluar.index')->with('success','Surat keluar diperbarui.');} public function destroy(SuratKeluar $suratKeluar){$suratKeluar->delete();return back()->with('success','Surat keluar dihapus.');} }
